package sqlglot

import "testing"

// Table options -- ENGINE, AUTO_INCREMENT, [DEFAULT] CHARACTER SET, COLLATE --
// held to what the pinned reference writes.
func TestTableOptions(t *testing.T) {
	written := 0
	for _, c := range [][3]string{
		{"", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INT) CHARACTER SET=utf8"},
		{"", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INT) CHARACTER SET=utf8mb4"},
		{"", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET=Latin1"},
		{"", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET='utf8'"},
		{"", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INT) AUTO_INCREMENT=10"},
		{"", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC"},
		{"", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INT) ROW_FORMAT=2"},
		{"tsql", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INTEGER) CHARACTER SET=utf8"},
		{"tsql", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INTEGER) CHARACTER SET=utf8mb4"},
		{"tsql", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INTEGER) DEFAULT CHARACTER SET=Latin1"},
		{"tsql", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INTEGER) DEFAULT CHARACTER SET='utf8'"},
		{"tsql", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INTEGER) COLLATE=utf8_bin"},
		{"tsql", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INTEGER) COLLATE=utf8_bin"},
		{"tsql", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INTEGER) AUTO_INCREMENT=10"},
		{"tsql", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INTEGER) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC"},
		{"tsql", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INTEGER) ROW_FORMAT=2"},
		{"postgres", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INT) CHARACTER SET=utf8"},
		{"postgres", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INT) CHARACTER SET=utf8mb4"},
		{"postgres", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET=Latin1"},
		{"postgres", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET='utf8'"},
		{"postgres", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"postgres", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"postgres", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INT) AUTO_INCREMENT=10"},
		{"postgres", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC"},
		{"postgres", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INT) ROW_FORMAT=2"},
		{"duckdb", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INT)"},
		{"duckdb", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INT)"},
		{"duckdb", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INT)"},
		{"duckdb", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INT)"},
		{"duckdb", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INT)"},
		{"duckdb", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INT)"},
		{"duckdb", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INT)"},
		{"duckdb", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INT)"},
		{"duckdb", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INT)"},
		{"databricks", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INT)"},
		{"databricks", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INT)"},
		{"databricks", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INT)"},
		{"databricks", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INT)"},
		{"databricks", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INT)"},
		{"databricks", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INT)"},
		{"databricks", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INT)"},
		{"databricks", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INT) COMMENT 'x' ROW_FORMAT=DYNAMIC"},
		{"databricks", "CREATE TABLE t (a INT) DEFAULT CHARSET=`utf8`", "CREATE TABLE t (a INT)"},
		{"databricks", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INT) ROW_FORMAT=2"},
		{"redshift", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INTEGER) CHARACTER SET=utf8"},
		{"redshift", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INTEGER) CHARACTER SET=utf8mb4"},
		{"redshift", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INTEGER) DEFAULT CHARACTER SET=Latin1"},
		{"redshift", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INTEGER) DEFAULT CHARACTER SET='utf8'"},
		{"redshift", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INTEGER) COLLATE=utf8_bin"},
		{"redshift", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INTEGER) COLLATE=utf8_bin"},
		{"redshift", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INTEGER) AUTO_INCREMENT=10"},
		{"redshift", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INTEGER) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC"},
		{"redshift", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INTEGER) ROW_FORMAT=2"},
		{"materialize", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INT) CHARACTER SET=utf8"},
		{"materialize", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INT) CHARACTER SET=utf8mb4"},
		{"materialize", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET=Latin1"},
		{"materialize", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET='utf8'"},
		{"materialize", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"materialize", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"materialize", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INT) AUTO_INCREMENT=10"},
		{"materialize", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC"},
		{"materialize", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INT) ROW_FORMAT=2"},
		{"risingwave", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INT) CHARACTER SET=utf8"},
		{"risingwave", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INT) CHARACTER SET=utf8mb4"},
		{"risingwave", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET=Latin1"},
		{"risingwave", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET='utf8'"},
		{"risingwave", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"risingwave", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"risingwave", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INT) AUTO_INCREMENT=10"},
		{"risingwave", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC"},
		{"risingwave", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INT) ROW_FORMAT=2"},
		{"fabric", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INT) CHARACTER SET=utf8"},
		{"fabric", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INT) CHARACTER SET=utf8mb4"},
		{"fabric", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET=Latin1"},
		{"fabric", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET='utf8'"},
		{"fabric", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"fabric", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"fabric", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INT) AUTO_INCREMENT=10"},
		{"fabric", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC"},
		{"fabric", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INT) ROW_FORMAT=2"},
		{"presto", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INTEGER) CHARACTER SET=utf8"},
		{"presto", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INTEGER) CHARACTER SET=utf8mb4"},
		{"presto", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INTEGER) DEFAULT CHARACTER SET=Latin1"},
		{"presto", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INTEGER) DEFAULT CHARACTER SET='utf8'"},
		{"presto", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INTEGER) COLLATE=utf8_bin"},
		{"presto", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INTEGER) COLLATE=utf8_bin"},
		{"presto", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INTEGER) AUTO_INCREMENT=10"},
		{"presto", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INTEGER) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin COMMENT 'x' ROW_FORMAT=DYNAMIC"},
		{"presto", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INTEGER) ROW_FORMAT=2"},
		{"trino", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INTEGER) CHARACTER SET=utf8"},
		{"trino", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INTEGER) CHARACTER SET=utf8mb4"},
		{"trino", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INTEGER) DEFAULT CHARACTER SET=Latin1"},
		{"trino", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INTEGER) DEFAULT CHARACTER SET='utf8'"},
		{"trino", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INTEGER) COLLATE=utf8_bin"},
		{"trino", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INTEGER) COLLATE=utf8_bin"},
		{"trino", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INTEGER) AUTO_INCREMENT=10"},
		{"trino", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INTEGER) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin COMMENT 'x' ROW_FORMAT=DYNAMIC"},
		{"trino", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INTEGER) ROW_FORMAT=2"},
		{"dremio", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INT) CHARACTER SET=utf8"},
		{"dremio", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INT) CHARACTER SET=utf8mb4"},
		{"dremio", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET=Latin1"},
		{"dremio", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET='utf8'"},
		{"dremio", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"dremio", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"dremio", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INT) AUTO_INCREMENT=10"},
		{"dremio", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC"},
		{"dremio", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INT) ROW_FORMAT=2"},
		{"mysql", "CREATE TABLE t (a INT) CHARACTER SET utf8", "CREATE TABLE t (a INT) CHARACTER SET=utf8"},
		{"mysql", "CREATE TABLE t (a INT) CHARSET = utf8mb4", "CREATE TABLE t (a INT) CHARACTER SET=utf8mb4"},
		{"mysql", "CREATE TABLE t (a INT) DEFAULT CHARSET=Latin1", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET=Latin1"},
		{"mysql", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET = 'utf8'", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET='utf8'"},
		{"mysql", "CREATE TABLE t (a INT) DEFAULT COLLATE utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"mysql", "CREATE TABLE t (a INT) COLLATE=utf8_bin", "CREATE TABLE t (a INT) COLLATE=utf8_bin"},
		{"mysql", "CREATE TABLE t (a INT) AUTO_INCREMENT=10", "CREATE TABLE t (a INT) AUTO_INCREMENT=10"},
		{"mysql", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC", "CREATE TABLE t (a INT) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='x' ROW_FORMAT=DYNAMIC"},
		{"mysql", "CREATE TABLE t (a INT) DEFAULT CHARSET=`utf8`", "CREATE TABLE t (a INT) DEFAULT CHARACTER SET=utf8"},
		{"mysql", "CREATE TABLE t (a INT) ROW_FORMAT = 2", "CREATE TABLE t (a INT) ROW_FORMAT=2"},
	} {
		tree, err := ParseOne(c[1], c[0])
		if err != nil {
			continue
		}
		got, err := Generate(tree, c[0])
		if err != nil {
			continue
		}
		written++
		if got != c[2] {
			t.Errorf("[%s] %s\n  want %s\n  got  %s", c[0], c[1], c[2], got)
		}
	}
	if written < 20 {
		t.Errorf("only %d statements were written back", written)
	}
}
